        if (len == 1 || frag[0] != '0') res.push_back(frag);
        for (int d = 1; d < len; d++) {
            string left = frag.substr(0, d), right = frag.substr(d);
            if ((left.length() == 1 || left[0] != '0') && right.back() != '0') {
                res.push_back(left + "." + right);
