class Solution {
    private List<String> getValid(String frag) {
        List<String> res = new ArrayList<>();
        int len = frag.length();
        if (len == 1 || frag.charAt(0) != '0') res.add(frag);
        for (int d = 1; d < len; d++) {
            String left = frag.substring(0, d);
            String right = frag.substring(d);
            if ((left.length() == 1 || left.charAt(0) != '0') && right.charAt(right.length() - 1) != '0') {
                res.add(left + "." + right);
            }
        }
        return res;
    }
    public List<String> ambiguousCoordinates(String s) {
        String digits = s.substring(1, s.length() - 1);
        int n = digits.length();
        List<String> ans = new ArrayList<>();
        for (int i = 1; i < n; i++) {
            List<String> leftCands = getValid(digits.substring(0, i));
            List<String> rightCands = getValid(digits.substring(i));
            for (String x : leftCands) {
                for (String y : rightCands) {
                    ans.add("(" + x + ", " + y + ")");
                }
            }
        }
        return ans;
    }
}

var ambiguousCoordinates = function(s) {
    const digits = s.slice(1, -1);
    const n = digits.length;
    function getValid(frag) {
        const res = [];
        const len = frag.length;
        if (len === 1 || frag[0] !== '0') res.push(frag);
        for (let d = 1; d < len; d++) {
            const left = frag.slice(0, d);
            const right = frag.slice(d);
            if ((left.length === 1 || left[0] !== '0') && right[right.length - 1] !== '0') {
                res.push(`${left}.${right}`);
            }
        }
        return res;
    }
    const ans = [];
    for (let i = 1; i < n; i++) {
        const leftCands = getValid(digits.slice(0, i));
        const rightCands = getValid(digits.slice(i));
        for (const x of leftCands) {
            for (const y of rightCands) {
                ans.push(`(${x}, ${y})`);
            }
